#!/bin/bash
set -euo pipefail
cd /data/test/colibri-head-batch-lROCPh
export CUDA_VISIBLE_DEVICES=0,1,2,3,4,5
export DSV4_CUDA=1 DSV4_CUDA_DEVICES=0,1,2,3,4,5
export OMP_NUM_THREADS=12 CTX=512 COLI_CUDA_ATTN_BATCH=1 COLI_CUDA_MOE_BATCH=1
export DSV4_CUDA_EXPERT_MIRRORS=2048 V4_LOADER_LANES=3 COLI_V4_PREWARM=0
export V4_DRAFT=5 V4_NGRAM=1 V4_MTP=0 V4_NGRAM_PARTIAL_KEEP=1
case "$1" in
 ngverify) modes=0v; rounds=1; tokens=160; prompt=repeat.txt ;;
 ngformal) modes=01; rounds=4; tokens=160; prompt=repeat.txt ;;
 ngdefault) modes=t0d; rounds=4; tokens=160; prompt=repeat.txt ;;
 longverify) modes=0v; rounds=1; tokens=192; prompt=long-repeat.txt ;;
 target) modes=t; rounds=2; tokens=160; prompt=repeat.txt ;;
 mtpcpu) modes=0vd; rounds=4; tokens=64; prompt=sky.txt; export V4_MTP=1 V4_MTP_GPU=0 V4_MTP_CONF=0 V4_NGRAM=0 V4_MTP_LOG=1 ;;
 mtpnopin) modes=0d; rounds=1; tokens=64; prompt=sky.txt; export V4_MTP=1 V4_MTP_GPU=1 V4_MTP_CONF=0 V4_NGRAM=0 V4_MTP_LOG=1 DSV4_CUDA_PIN_HOST=0 ;;
 mtpverify) modes=0v; rounds=1; tokens=64; prompt=sky.txt; export V4_MTP=1 V4_MTP_GPU=1 V4_MTP_CONF=0 V4_NGRAM=0 V4_MTP_LOG=1 ;;
 mtpformal) modes=0d; rounds=4; tokens=64; prompt=sky.txt; export V4_MTP=1 V4_MTP_GPU=1 V4_MTP_CONF=0 V4_NGRAM=0 V4_MTP_LOG=1 ;;
 *) exit 2 ;;
esac
exec timeout -k 10 900 c/tools/bench_dsv4_head_batch /data/models/DeepSeek-V4-Flash-0731 "$prompt" "$tokens" "$rounds" "$modes" > "$1.jsonl" 2> "$1.log"
